//! An object's `<surface>` CRG adds to the road height under it, inside its
//! box, and may hide the road's own `attached` CRG.
//!
//! `object_surface.xodr` is generated by `scenariogeneration` (see
//! `object_surface.py`). Its roads are flat straights heading +X, so a road
//! station is a point in closed form. The CRG files are made here: planes,
//! which a bilinear grid holds exactly.

use opencrg::{CrgGrid, Uv};
use xodr::{
    load_file_with_provenance, CrgMode, Provenance, RoadNetwork, RoadSurface, SurfaceHint,
    SurfaceSample, Warning,
};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/data/object_surface.xodr"
);

/// A CRG file of `value(u, v)` for `u` from `start` over `length` metres and
/// `v` across `2 * half`, on a straight reference line.
fn grid(start: f64, length: f64, half: f64, value: impl Fn(f64, f64) -> f64) -> CrgGrid {
    let step = 0.25;
    let columns = (2.0 * half / step) as usize + 1;
    let rows = (length / step) as usize + 1;
    let mut text = format!(
        "$ROAD_CRG\nREFERENCE_LINE_START_U = {start}\nREFERENCE_LINE_INCREMENT = {step}\n\
         LONG_SECTION_V_RIGHT = {}\nLONG_SECTION_V_INCREMENT = {step}\n$\n$KD_Definition\n#:LRFI\n",
        -half
    );
    for c in 0..columns {
        text += &format!("D:long section {},m\n", c + 1);
    }
    text += "$\n$$$$\n";
    for r in 0..rows {
        for c in 0..columns {
            let z = value(start + r as f64 * step, -half + c as f64 * step);
            text += &format!("{z:10.6}");
            if c % 8 == 7 || c == columns - 1 {
                text += "\n";
            }
        }
    }
    CrgGrid::from_bytes(text.as_bytes()).expect("the generated CRG loads")
}

fn plate() -> CrgGrid {
    grid(-2.0, 4.0, 2.0, |u, v| 0.05 * u - 0.03 * v + 0.01)
}

/// A plane over the metre either side of `v` 0 up to `u` 0.5, and no
/// value, NaN, beyond. Its reference line starts with a value, which OpenCRG
/// needs to level the file.
fn small() -> CrgGrid {
    grid(-1.0, 2.0, 1.0, |u, v| {
        if u > 0.5 || v.abs() > 0.5 {
            f64::NAN
        } else {
            0.02 * u + 0.04 * v + 0.02
        }
    })
}

fn road() -> CrgGrid {
    grid(0.0, 100.0, 5.0, |u, v| 0.01 * u + 0.02 * v + 0.005)
}

fn load(name: &str) -> Option<CrgGrid> {
    match name {
        "plate.crg" => Some(plate()),
        "small.crg" => Some(small()),
        "road.crg" => Some(road()),
        _ => None,
    }
}

/// `crgEvaluv2z` of `grid` at `(u, v)`.
fn eval(grid: &CrgGrid, u: f64, v: f64) -> f64 {
    grid.elevation_at_uv(Uv { u, v }).expect("inside the file")
}

/// The raw grid value of `grid` at `(u, v)`, which an `attached` road CRG
/// adds.
fn bump(grid: &CrgGrid, u: f64, v: f64) -> f64 {
    grid.grid_at_uv(Uv { u, v }).expect("inside the file").z
}

fn network() -> (RoadNetwork, Provenance) {
    load_file_with_provenance(FIXTURE).expect("import")
}

/// The point `(u, v)` in the frame of an object at `(x, y)` heading `hdg`.
fn at_object((x, y): (f64, f64), hdg: f64, (u, v): (f64, f64)) -> (f64, f64) {
    let (sin, cos) = hdg.sin_cos();
    (x + u * cos - v * sin, y + u * sin + v * cos)
}

fn sample(surface: &RoadSurface, (x, y): (f64, f64)) -> SurfaceSample {
    surface
        .sample(x, y, &mut SurfaceHint::default())
        .expect("on the road")
}

fn assert_near(got: f64, want: f64, what: &str) {
    assert!((got - want).abs() < 1e-6, "{what}: got {got}, want {want}");
}

#[test]
fn an_object_crg_adds_to_the_road_in_its_own_turned_frame() {
    let (net, _) = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    let (u, v) = (0.6, -0.4);
    let got = sample(&surface, at_object((20.0, -1.75), 0.5, (u, v)));
    let want = 2.0 * eval(&plate(), u, v);
    assert_near(got.z, want, "plate");
    assert_near(got.crg_height.expect("a CRG answered"), want, "crg height");
}

#[test]
fn an_object_crg_tilts_the_normal_by_its_slope() {
    let (net, _) = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    let (x, y) = at_object((20.0, -1.75), 0.5, (0.6, -0.4));
    let h = 1e-3;
    let z = |dx: f64, dy: f64| sample(&surface, (x + dx, y + dy)).z;
    let gx = (z(h, 0.0) - z(-h, 0.0)) / (2.0 * h);
    let gy = (z(0.0, h) - z(0.0, -h)) / (2.0 * h);
    let length = (gx * gx + gy * gy + 1.0).sqrt();
    let want = [-gx / length, -gy / length, 1.0 / length];
    let got = sample(&surface, (x, y)).normal;
    for (g, w) in got.iter().zip(want) {
        assert!((g - w).abs() < 1e-4, "normal {got:?}, want {want:?}");
    }
    assert!(gx.abs() > 0.01, "the plate slopes, so the normal tilts");
}

#[test]
fn an_object_crg_plays_no_part_outside_its_box() {
    let (net, _) = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    let got = sample(&surface, at_object((20.0, -1.75), 0.5, (1.5, 0.0)));
    assert_near(got.z, 0.0, "beside the plate");
    assert_eq!(got.crg_height, None);
}

#[test]
fn an_object_crg_with_no_value_leaves_the_road_as_it_is() {
    let (net, _) = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    let inside = sample(&surface, at_object((30.0, 1.75), 0.0, (0.2, 0.1)));
    assert_near(inside.z, eval(&small(), 0.2, 0.1), "on the file");
    let beyond = sample(&surface, at_object((30.0, 1.75), 0.0, (0.8, 0.0)));
    assert_near(beyond.z, 0.0, "in the box, off the file");
    assert_eq!(beyond.crg_height, None);
}

#[test]
fn each_copy_of_a_discrete_repeat_has_its_own_crg() {
    let (net, _) = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    for s in [50.0, 60.0, 70.0] {
        let got = sample(&surface, at_object((s, -1.75), 0.0, (0.3, 0.2)));
        assert_near(got.z, eval(&plate(), 0.3, 0.2), &format!("hole at {s}"));
    }
    let objects = net
        .crg_surfaces()
        .iter()
        .filter(|c| matches!(c.mode, CrgMode::Object(_)))
        .count();
    assert_eq!(objects, 1 + 1 + 3 + 1 + 2 + 2 + 1);
}

#[test]
fn an_object_crg_that_hides_the_road_crg_replaces_its_bumps() {
    let (net, _) = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    let (u, v) = (0.3, 0.2);
    let got = sample(&surface, at_object((20.0, 38.25), 0.0, (u, v)));
    assert_near(got.z, eval(&plate(), u, v), "hider");
    let open = sample(&surface, (40.0, 38.25));
    assert_near(open.z, bump(&road(), 40.0, -1.75), "between the objects");
}

#[test]
fn an_object_crg_that_does_not_hide_stacks_on_the_road_crg() {
    let (net, _) = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    let (u, v) = (0.3, 0.2);
    let got = sample(&surface, at_object((60.0, 38.25), 0.0, (u, v)));
    let want = bump(&road(), 60.0 + u, -1.75 + v) + eval(&plate(), u, v);
    assert_near(got.z, want, "stacker");
}

#[test]
fn an_object_crg_cannot_hide_a_road_crg_that_replaces_the_height() {
    let (net, provenance) = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    let (u, v) = (0.3, 0.2);
    for s in [20.0, 60.0] {
        let got = sample(&surface, at_object((s, 78.25), 0.0, (u, v)));
        let want = eval(&road(), s + u, -1.75 + v) + eval(&plate(), u, v);
        assert_near(got.z, want, &format!("road 3 at {s}"));
    }
    let clashes: Vec<&str> = provenance
        .warnings
        .iter()
        .filter_map(|w| match w {
            Warning::CrgHideIgnored { object_id, .. } => Some(object_id.as_str()),
            _ => None,
        })
        .collect();
    assert_eq!(clashes, ["clash"]);
}

#[test]
fn a_junction_objects_crg_covers_the_junctions_lanes() {
    let (net, _) = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    let (u, v) = (0.3, 0.2);
    let got = sample(&surface, at_object((1000.0, 1.0), 0.0, (u, v)));
    assert_near(got.z, eval(&plate(), u, v), "grate");
}

#[test]
fn a_surface_on_an_object_with_no_box_is_dropped_with_a_warning() {
    let (_, provenance) = network();
    let dropped: Vec<&str> = provenance
        .warnings
        .iter()
        .filter_map(|w| match w {
            Warning::ObjectSurfaceDropped { object_id, .. } => Some(object_id.as_str()),
            _ => None,
        })
        .collect();
    assert_eq!(dropped, ["disc"]);
}

#[test]
fn a_pitched_and_rolled_objects_crg_turns_by_its_heading_alone() {
    let (net, _) = network();
    let mesh = net.surface_mesh();
    let surface = RoadSurface::new(&net, &mesh, load);
    let (u, v) = (0.6, -0.4);
    let got = sample(&surface, at_object((90.0, -1.75), 0.4, (u, v)));
    assert_near(got.z, eval(&plate(), u, v), "tilted");
}
